package com.brightloop.controller;

import com.brightloop.model.*;import com.brightloop.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.context.annotation.Configuration;import org.springframework.scheduling.annotation.EnableScheduling;
import java.math.*;import java.time.*;import java.util.*;import org.springframework.transaction.annotation.Transactional;import jakarta.servlet.http.HttpSession;

@RestController @RequestMapping("/api") @CrossOrigin
public class ApiController {
 private final AppUserRepository users; private final ProductRepository products; private final ProductVariantRepository variants; private final PlanRepository plans; private final CustomerRepository customers; private final SubscriptionRepository subscriptions; private final InvoiceRepository invoices; private final PaymentRepository payments; private final DiscountRuleRepository discounts; private final PasswordEncoder encoder;
 public ApiController(AppUserRepository u,ProductRepository p,ProductVariantRepository v,PlanRepository pl,CustomerRepository c,SubscriptionRepository s,InvoiceRepository i,PaymentRepository pay,DiscountRuleRepository d,PasswordEncoder e){users=u;products=p;variants=v;plans=pl;customers=c;subscriptions=s;invoices=i;payments=pay;discounts=d;encoder=e;}
 @PostMapping("/auth/signup") public ResponseEntity<?> signup(@RequestBody Map<String,String> b){String email=b.getOrDefault("email","").trim().toLowerCase(Locale.ROOT),pw=b.getOrDefault("password","");if(!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))return ResponseEntity.badRequest().body(Map.of("error","Valid email required"));if(pw.length()<=8||!pw.matches(".*[A-Z].*")||!pw.matches(".*[a-z].*")||!pw.matches(".*[^A-Za-z0-9].*"))return ResponseEntity.badRequest().body(Map.of("error","Password must be >8 chars and include uppercase, lowercase and special character"));if(users.existsByEmail(email))return ResponseEntity.status(409).body(Map.of("error","Email already registered"));AppUser u=new AppUser();u.email=email;u.fullName=b.getOrDefault("fullName","Customer");u.passwordHash=encoder.encode(pw);u.role=AppUser.Role.CUSTOMER;users.save(u);if(!customers.existsByEmail(email)){Customer c=new Customer();c.name=u.fullName;c.email=email;customers.save(c);}return ResponseEntity.ok(Map.of("id",u.id,"message","Account created"));}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@RequestBody Map<String,String>b,HttpSession session){return users.findByEmail(b.getOrDefault("email"," ").trim().toLowerCase(Locale.ROOT)).filter(u->encoder.matches(b.getOrDefault("password",""),u.passwordHash)).<ResponseEntity<?>>map(u->{session.setAttribute("USER_ID",u.id);session.setAttribute("USER_EMAIL",u.email);session.setAttribute("USER_NAME",u.fullName);session.setAttribute("USER_ROLE",u.role.name());return ResponseEntity.ok(Map.of("id",u.id,"email",u.email,"name",u.fullName,"role",u.role));}).orElseGet(()->ResponseEntity.status(401).body(Map.of("error","Invalid email or password")));}
 @GetMapping("/auth/me") public ResponseEntity<?> me(HttpSession session){Object id=session.getAttribute("USER_ID");if(id==null)return ResponseEntity.status(401).body(Map.of("error","Not signed in"));return ResponseEntity.ok(Map.of("id",id,"email",session.getAttribute("USER_EMAIL"),"name",session.getAttribute("USER_NAME"),"role",session.getAttribute("USER_ROLE")));}
 @PostMapping("/auth/logout") public ResponseEntity<?> logout(HttpSession session){session.invalidate();return ResponseEntity.ok(Map.of("message","Signed out"));}
 @GetMapping("/customer/subscriptions") public List<Subscription> mySubscriptions(HttpSession session){String email=(String)session.getAttribute("USER_EMAIL");return subscriptions.findByCustomerEmail(email);}
 @GetMapping("/users") public List<Map<String,Object>> listUsers(){return users.findAll().stream().map(u->Map.<String,Object>of("id",u.id,"email",u.email,"name",u.fullName,"role",u.role)).toList();}
 @PostMapping("/users") public ResponseEntity<?> createUser(@RequestBody Map<String,String>b){String email=b.getOrDefault("email","").trim().toLowerCase(Locale.ROOT),pw=b.getOrDefault("password","");if(!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))return ResponseEntity.badRequest().body(Map.of("error","Valid email required"));if(pw.length()<9)return ResponseEntity.badRequest().body(Map.of("error","Password must be at least 9 characters"));if(users.existsByEmail(email))return ResponseEntity.status(409).body(Map.of("error","Email already registered"));AppUser u=new AppUser();u.email=email;u.fullName=b.getOrDefault("fullName","New user");u.passwordHash=encoder.encode(pw);try{u.role=AppUser.Role.valueOf(b.getOrDefault("role","CUSTOMER").toUpperCase(Locale.ROOT));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Role must be ADMIN, SALES or CUSTOMER"));}users.save(u);if(u.role==AppUser.Role.CUSTOMER&&!customers.existsByEmail(email)){Customer c=new Customer();c.name=u.fullName;c.email=email;customers.save(c);}return ResponseEntity.ok(Map.of("id",u.id,"email",u.email,"name",u.fullName,"role",u.role));}

 @PostMapping("/auth/staff") public ResponseEntity<?> addStaff(@RequestBody Map<String,String>b){String email=b.getOrDefault("email","").trim().toLowerCase(Locale.ROOT);if(!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))return ResponseEntity.badRequest().body(Map.of("error","Valid email required"));if(users.existsByEmail(email))return ResponseEntity.status(409).body(Map.of("error","Email exists"));String pw=b.getOrDefault("password","Staff@12345");if(pw.length()<9)return ResponseEntity.badRequest().body(Map.of("error","Password must be at least 9 characters"));AppUser u=new AppUser();u.email=email;u.fullName=b.getOrDefault("fullName","Staff");u.passwordHash=encoder.encode(pw);u.role=AppUser.Role.SALES;return ResponseEntity.ok(users.save(u));}
 @GetMapping("/products") public List<Product> products(){return products.findAll();} @PostMapping("/products") public Product createProduct(@RequestBody Product p){return products.save(p);} @PostMapping("/products/{id}/variants") public ProductVariant variant(@PathVariable Long id,@RequestBody ProductVariant v){v.product=products.findById(id).orElseThrow();return variants.save(v);}
 @GetMapping("/plans") public List<Plan> plans(){return plans.findAll();} @PostMapping("/plans") public Plan createPlan(@RequestBody Plan p){if(p.name==null||p.name.isBlank())throw new IllegalArgumentException("Plan name is required");if(p.interval==null)p.interval=Plan.Interval.MONTHLY;if(p.price==null||p.price.signum()<0)throw new IllegalArgumentException("Plan price cannot be negative");if(p.minimumQuantity<1)throw new IllegalArgumentException("Minimum quantity must be at least 1");if(p.availableFrom!=null&&p.availableUntil!=null&&p.availableUntil.isBefore(p.availableFrom))throw new IllegalArgumentException("Plan end date cannot be before start date");return plans.save(p);}
 @GetMapping("/customers") public List<Customer> customers(){return customers.findAll();} @PostMapping("/customers") public Customer createCustomer(@RequestBody Customer c){if(c.name==null||c.name.isBlank())throw new IllegalArgumentException("Customer name is required");if(c.email==null||!c.email.trim().matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Valid customer email is required");c.email=c.email.trim().toLowerCase(Locale.ROOT);return customers.save(c);}
 @GetMapping("/subscriptions") public List<Subscription> subscriptions(){return subscriptions.findAll();} @PostMapping("/subscriptions") @Transactional public Subscription createSubscription(@RequestBody Subscription s){if(s.customer==null||s.customer.id==null||s.plan==null||s.plan.id==null)throw new IllegalArgumentException("Select a valid customer and plan");s.customer=customers.findById(s.customer.id).orElseThrow(()->new IllegalArgumentException("Customer not found"));s.plan=plans.findById(s.plan.id).orElseThrow(()->new IllegalArgumentException("Plan not found"));if(!s.plan.active)throw new IllegalArgumentException("Selected plan is inactive");LocalDate today=LocalDate.now();if(s.plan.availableFrom!=null&&today.isBefore(s.plan.availableFrom))throw new IllegalArgumentException("Plan is not available yet");if(s.plan.availableUntil!=null&&today.isAfter(s.plan.availableUntil))throw new IllegalArgumentException("Plan is no longer available");if(s.number==null||s.number.isBlank())s.number="SUB-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);if(s.quantity<Math.max(1,s.plan.minimumQuantity))throw new IllegalArgumentException("Quantity is below the plan minimum of "+s.plan.minimumQuantity);if(s.unitPrice==null||s.unitPrice.signum()==0)s.unitPrice=s.plan.price;if(s.unitPrice==null||s.unitPrice.signum()<0)throw new IllegalArgumentException("Unit price cannot be negative");if(s.taxRate==null)s.taxRate=new BigDecimal("0.18");if(s.taxRate.signum()<0||s.taxRate.compareTo(BigDecimal.ONE)>0)throw new IllegalArgumentException("Tax rate must be between 0 and 1 (for example, 0.18 for 18%)");if(s.discountAmount==null)s.discountAmount=BigDecimal.ZERO;if(s.discountAmount.signum()<0)throw new IllegalArgumentException("Discount cannot be negative");if(s.startDate==null)s.startDate=today;if(s.nextBillingDate==null)s.nextBillingDate=s.startDate;if(s.status==null)s.status=Subscription.Status.ACTIVE;return subscriptions.save(s);}
 @PutMapping("/subscriptions/{id}/status") public Subscription status(@PathVariable Long id,@RequestBody Map<String,String>b){Subscription s=subscriptions.findById(id).orElseThrow();String requested=b.get("status");if(requested==null||requested.isBlank())throw new IllegalArgumentException("Subscription status is required");try{s.status=Subscription.Status.valueOf(requested.trim().toUpperCase(Locale.ROOT));}catch(IllegalArgumentException ex){throw new IllegalArgumentException("Invalid subscription status");}if(s.status==Subscription.Status.PAUSED&&!s.plan.allowPause)throw new IllegalStateException("Pausing is disabled for this plan");if(s.status==Subscription.Status.CLOSED&&!s.plan.allowEarlyClose)throw new IllegalStateException("Early closure is disabled for this plan");if(s.status==Subscription.Status.CLOSED)s.expiryDate=LocalDate.now();return subscriptions.save(s);}
 @PostMapping("/subscriptions/{id}/renew") public Subscription renew(@PathVariable Long id){Subscription s=subscriptions.findById(id).orElseThrow();if(!s.plan.allowRenew)throw new IllegalStateException("Renewal is disabled for this plan");if(s.status!=Subscription.Status.CLOSED)throw new IllegalStateException("Only closed subscriptions can be renewed");s.status=Subscription.Status.ACTIVE;s.startDate=s.expiryDate==null?LocalDate.now():s.expiryDate.plusDays(1);s.nextBillingDate=s.startDate;s.expiryDate=null;return subscriptions.save(s);}
 @GetMapping("/invoices") public List<Invoice> invoices(){return invoices.findAll();} @PostMapping("/invoices/generate/{subscriptionId}") @Transactional public Invoice generate(@PathVariable Long subscriptionId){Subscription s=subscriptions.findById(subscriptionId).orElseThrow();LocalDate date=LocalDate.now();if(invoices.existsBySubscriptionIdAndInvoiceDate(s.id,date))throw new IllegalStateException("Invoice already generated for this subscription today");return makeInvoice(s,date);}
 private Invoice makeInvoice(Subscription s,LocalDate date){Invoice i=new Invoice();i.number="INV-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();i.subscription=s;i.customer=s.customer;i.invoiceDate=date;i.dueDate=date.plusDays(14);i.subtotal=s.unitPrice.multiply(BigDecimal.valueOf(s.quantity));i.discount=(s.discountAmount==null?BigDecimal.ZERO:s.discountAmount).min(i.subtotal).max(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP);BigDecimal taxable=i.subtotal.subtract(i.discount).max(BigDecimal.ZERO);i.tax=taxable.multiply(s.taxRate==null?BigDecimal.ZERO:s.taxRate).setScale(2,RoundingMode.HALF_UP);i.total=taxable.add(i.tax);i.status=Invoice.Status.CONFIRMED;i.description=s.plan.name+" subscription billing";Invoice saved=invoices.save(i);s.nextBillingDate=nextDate(date,s.plan.interval);subscriptions.save(s);return saved;}
 private LocalDate nextDate(LocalDate d,Plan.Interval x){return switch(x){case DAILY->d.plusDays(1);case WEEKLY->d.plusWeeks(1);case MONTHLY->d.plusMonths(1);case YEARLY->d.plusYears(1);};}
 @PostMapping("/invoices/{id}/confirm") public Invoice confirm(@PathVariable Long id){Invoice i=invoices.findById(id).orElseThrow();i.status=Invoice.Status.CONFIRMED;return invoices.save(i);}
 @PostMapping("/invoices/{id}/cancel") public Invoice cancel(@PathVariable Long id){Invoice i=invoices.findById(id).orElseThrow();i.status=Invoice.Status.CANCELLED;return invoices.save(i);}
 @GetMapping("/payments") public List<Payment> payments(){return payments.findAll();}
 @PostMapping("/payments") @Transactional public Payment payment(@RequestBody Payment p){if(p.invoice==null||p.invoice.id==null)throw new IllegalArgumentException("Invoice is required");Invoice i=invoices.findById(p.invoice.id).orElseThrow(()->new IllegalArgumentException("Invoice not found"));if(i.status==Invoice.Status.CANCELLED)throw new IllegalArgumentException("Cannot pay a cancelled invoice");if(p.amount==null||p.amount.signum()<=0)throw new IllegalArgumentException("Payment amount must be positive");if((i.paidAmount==null?BigDecimal.ZERO:i.paidAmount).add(p.amount).compareTo(i.total)>0)throw new IllegalArgumentException("Payment exceeds invoice balance");if(p.paymentDate==null)p.paymentDate=LocalDate.now();p.invoice=i;Payment saved=payments.save(p);i.paidAmount=(i.paidAmount==null?BigDecimal.ZERO:i.paidAmount).add(p.amount);if(i.paidAmount.compareTo(i.total)>=0)i.status=Invoice.Status.PAID;invoices.save(i);return saved;}
 @GetMapping("/discounts") public List<DiscountRule> discounts(){return discounts.findAll();} @PostMapping("/discounts") public DiscountRule discount(@RequestBody DiscountRule d){if(d.name==null||d.name.isBlank())throw new IllegalArgumentException("Discount name is required");if(d.kind==null||d.value==null||d.value.signum()<=0)throw new IllegalArgumentException("A positive discount value and type are required");if(d.kind==DiscountRule.Kind.PERCENTAGE&&d.value.compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException("Percentage discount cannot exceed 100%");if(d.minimumPurchase!=null&&d.minimumPurchase.signum()<0)throw new IllegalArgumentException("Minimum purchase cannot be negative");if(d.minimumQuantity!=null&&d.minimumQuantity<1)throw new IllegalArgumentException("Minimum quantity must be at least 1");if(d.usageLimit!=null&&d.usageLimit<1)throw new IllegalArgumentException("Usage limit must be at least 1");if(d.startDate!=null&&d.endDate!=null&&d.endDate.isBefore(d.startDate))throw new IllegalArgumentException("End date cannot be before start date");if(d.usedCount<0)d.usedCount=0;return discounts.save(d);}
 @PostMapping("/subscriptions/{id}/apply-discount/{discountId}") @Transactional public Subscription applyDiscount(@PathVariable Long id,@PathVariable Long discountId){Subscription s=subscriptions.findById(id).orElseThrow();DiscountRule d=discounts.findById(discountId).orElseThrow();LocalDate today=LocalDate.now();if(!d.active||!d.appliesToSubscription||(d.product!=null)||(d.startDate!=null&&today.isBefore(d.startDate))||(d.endDate!=null&&today.isAfter(d.endDate))||(d.usageLimit!=null&&d.usedCount>=d.usageLimit))throw new IllegalStateException("Discount is not currently eligible");if(s.discountAmount!=null&&s.discountAmount.signum()>0)throw new IllegalStateException("A discount has already been applied to this subscription");BigDecimal base=s.unitPrice.multiply(BigDecimal.valueOf(s.quantity));if(d.minimumPurchase!=null&&base.compareTo(d.minimumPurchase)<0)throw new IllegalStateException("Minimum purchase not met");if(d.minimumQuantity!=null&&s.quantity<d.minimumQuantity)throw new IllegalStateException("Minimum quantity not met");if(d.value==null||d.value.signum()<=0)throw new IllegalStateException("Discount value must be positive");if(d.kind==DiscountRule.Kind.PERCENTAGE&&d.value.compareTo(new BigDecimal("100"))>0)throw new IllegalStateException("Percentage discount cannot exceed 100%");BigDecimal amount=d.kind==DiscountRule.Kind.PERCENTAGE?base.multiply(d.value).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP):d.value;s.discountAmount=amount.min(base).setScale(2,RoundingMode.HALF_UP);d.usedCount++;discounts.save(d);return subscriptions.save(s);}
 @GetMapping("/dashboard/summary") public Map<String,Object> dashboard(){List<Invoice> all=invoices.findAll();BigDecimal revenue=all.stream().map(i->i.paidAmount==null?BigDecimal.ZERO:i.paidAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal owed=all.stream().filter(i->i.status!=Invoice.Status.CANCELLED).map(i->i.total.subtract(i.paidAmount==null?BigDecimal.ZERO:i.paidAmount).max(BigDecimal.ZERO)).reduce(BigDecimal.ZERO,BigDecimal::add);long overdue=all.stream().filter(i->i.status!=Invoice.Status.PAID&&i.status!=Invoice.Status.CANCELLED&&i.dueDate!=null&&i.dueDate.isBefore(LocalDate.now())).count();List<Subscription> activeSubs=subscriptions.findByStatus(Subscription.Status.ACTIVE);long active=activeSubs.size();BigDecimal mrr=activeSubs.stream().map(s->{BigDecimal monthly=s.unitPrice.multiply(BigDecimal.valueOf(s.quantity));return switch(s.plan.interval==null?Plan.Interval.MONTHLY:s.plan.interval){case DAILY->monthly.multiply(new BigDecimal("30.4375"));case WEEKLY->monthly.multiply(new BigDecimal("52")).divide(new BigDecimal("12"),4,RoundingMode.HALF_UP);case MONTHLY->monthly;case YEARLY->monthly.divide(new BigDecimal("12"),4,RoundingMode.HALF_UP);};}).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);return Map.of("monthlyRecurringRevenue",mrr,"activeSubscriptions",active,"revenueCollected",revenue,"outstanding",owed,"overdueInvoices",overdue,"totalSubscriptions",subscriptions.count(),"totalInvoices",invoices.count());}
 @GetMapping("/dashboard/overdue") public List<Invoice> overdue(){return invoices.findAll().stream().filter(i->i.status!=Invoice.Status.PAID&&i.status!=Invoice.Status.CANCELLED&&i.dueDate!=null&&i.dueDate.isBefore(LocalDate.now())).toList();}
}
@Configuration @EnableScheduling class BillingScheduler { private final SubscriptionRepository subscriptions;private final InvoiceRepository invoices;private final ApiController api;BillingScheduler(SubscriptionRepository s,InvoiceRepository i,ApiController a){subscriptions=s;invoices=i;api=a;} @Scheduled(cron="0 0 2 * * *") public void recurringBilling(){LocalDate today=LocalDate.now();for(Subscription s:subscriptions.findByStatus(Subscription.Status.ACTIVE)){if(s.nextBillingDate!=null&&!s.nextBillingDate.isAfter(today)&&!invoices.existsBySubscriptionIdAndInvoiceDate(s.id,today)){try{api.generate(s.id);}catch(Exception ignored){}}}}}
